import{z as h,x as o,o as n,c as A,q as E,j as i,D as r,d as e,s as m,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"psi 与 charm 的日常","description":"","frontmatter":{"title":"psi 与 charm 的日常","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-vanna-charm-daily.md","filePath":"quant/omm-vanna-charm-daily.md","lastUpdated":1791413859000}'),B={name:"quant/omm-vanna-charm-daily.md"};function d(p,a,c,D,u,f){const l=o("Mermaid");return n(),A("div",null,[a[2]||(a[2]=E('<h1 id="psi-与-charm-的日常" tabindex="-1">psi 与 charm 的日常 <a class="header-anchor" href="#psi-与-charm-的日常" aria-label="Permalink to &quot;psi 与 charm 的日常&quot;">​</a></h1><div class="epigraph"><p>现货不动、波动不动，账本也在走：时钟是唯一不会缺席的对手盘，vanna 与 charm 是它写在 Delta 上的两个签名。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives 希腊字母各章；二阶偏导的运营口径见高阶希腊课程</footer></div><p><a href="/quant/omm-event-positioning">上一课</a>把日历上已知的集中风险排进了台账。事件之外，日历本身每天都在改写账本：即使现货与隐波一动不动，Delta 与 Gamma 也随时间漂移。本课写 <strong>vanna</strong>（\\(\\partial^2 V/\\partial S\\,\\partial\\sigma\\)，亦即 Delta 对波动）与 <strong>charm</strong>（\\(\\partial\\Delta/\\partial t\\)，Delta 对时间）的日常管理——把隔夜漂移从「开盘的意外」变成「收盘的排班」。</p><p>先钉记号，因为名字在系统间并不统一：有的终端把 vanna 写成 dvega/dspot，有的手册用 psi 记别的偏导（例如对股息收益率的敏感度）。名字可以各叫各的，偏导定义必须钉进 <a href="/quant/omm-book-layering">账本</a> 的字段，否则两套系统对同一仓位算出的「vanna」不可相加。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只把 Delta 对到零就收工的台，第二天开盘面对的不再是零：时间过了，剩余方差 \\(\\sigma^2\\tau\\) 减少，密度向执行价集中，Delta 被推离原位；波动一跳，贴值区的 Delta 更是立刻变号。 <a href="/quant/higher-greeks">Charm / Color 高阶希腊</a> 给出了这些偏导的公式与形状，本课不重推，只解决运营问题：漂移有多大、何时预留、排给谁执行、错了怎么兜住。</p><p>做市台比方向性账户更敏感：报价者持有大量贴值短到期仓位，charm 不是隔夜项而是盘中项；<a href="/quant/pin-risk">到期周</a> 与 <a href="/quant/zero-dte-microstructure">0DTE</a> 午后，Delta 的半衰期以小时计。</p><p><span class="marginnote">术语翻译：charm 就是「放着什么都不动，Delta 自己会走多少」——像牛奶有保质期，Delta 也有「时保期」；vanna 则是「隐波一动，Delta 跟着歪多少」。两者都不是新资产，只是 Delta 这个数会随时间和波动自己漂移。</span></p><h3 id="每日例行" tabindex="-1">每日例行 <a class="header-anchor" href="#每日例行" aria-label="Permalink to &quot;每日例行&quot;">​</a></h3><p>收盘流程固定三步。其一，算 \\(\\mathrm{Charm}\\times\\Delta t\\) 到次日可对冲时刻，得到「时钟项」漂移；其二，算 vanna 的隔夜情景（例如现货 \\(\\pm 1\\%\\) 乘隐波 \\(\\pm 1\\) 个点的四种组合），得到「波动项」漂移区间；其三，把目标 Delta 设为零加上一个偏移——有隔夜观点就偏向观点一侧，没有就按漂移区间中点预留。漂移写进晨会对冲计划，按执行成本排序：先补漂移最大、流动性最好的桶。</p><p><span class="marginnote">数字实例：收盘算得 charm 漂移 −0.3% Delta，vanna 四情景（现货 ±1% 乘隐波 ±1 点）给出 +0.2% 至 −0.5% 的区间，偏移就取区间中点 −0.15%：目标 Delta 不设 0，而设 +0.15%。开盘时真实 Delta 大概率已落进带宽，不必抢跑。</span></p><p><span class="marginnote">量级参考 <a href="/quant/higher-greeks">Charm / Color</a>：隔夜 charm 漂移可相当于几个百分点的 Delta，到期周贴值档按小时计。别用全年线性外推——charm 随 \\(\\tau\\) 以 \\(1/\\sqrt{\\tau}\\) 的速度变，周中与到期周不是同一个数；股息日例外，除息的 Delta 跳动按 <a href="/quant/discrete-dividend-am">离散股息</a> 单独处理，不是 charm。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预留偏移是对冲，不是预测。 Charm 预留的对价是放弃漂移顺风的可能收益，换来开盘不用抢跑；是否值得用 <a href="/quant/delta-hedge-freq">对冲频率</a> 的框架算：预留成本对漂移概率加权，低于抢跑的滑点就预留。执行排班交给 <a href="/quant/omm-hedge-execution">对冲执行</a> 的规则表：时钟项可挂单慢慢补，波动项留到事件窗后按实现值补。Vanna 的存量风险则看聚合口径：把整本按 <a href="/quant/dealer-vanna-charm-flows">经销商 Vanna / Charm 流</a> 的方法聚合成市场级对冲需求，符号取决于自家库存方向——这正是记号与定义必须先钉死的原因。</p>',14)),(n(),i(s,null,{default:r(()=>[m(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%94%B6%E7%9B%98%E8%B4%A6%E6%9C%AC%22%5D%20--%3E%20B%5B%22%E6%97%B6%E9%92%9F%E9%A1%B9%20Charm%C3%97%CE%94t%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%B3%A2%E5%8A%A8%E9%A1%B9%20Vanna%20%E6%83%85%E6%99%AF%E5%8C%BA%E9%97%B4%22%5D%0A%20%20B%20--%3E%20D%5B%22%E7%9B%AE%E6%A0%87%20Delta%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E6%99%A8%E4%BC%9A%E5%AF%B9%E5%86%B2%E6%8E%92%E7%8F%AD%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%89%A7%E8%A1%8C%E4%B8%8E%E5%88%B0%E8%BE%BE%E4%BB%B7%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%94%B6%E7%9B%98%E5%A4%8D%E6%A0%B8%20%E6%BC%82%E7%A7%BB%E5%AE%9E%E7%8E%B0%E5%80%BC%22%5D%0A%20%20G%20--%3E%20A%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("机制上，vanna 与 charm 不是新风险源，而是同一价格函数在「现货 \\(\\times\\) 波动」与「时间」方向上的曲率与漂移。它们改变的是"),t("strong",null,"对冲的时间结构"),e("：Gamma 决定现货每动一格要补多少，vanna 决定波动每动一格要补多少，charm 决定什么都不动也要补多少。三者共用一张 "),t("a",{href:"/quant/omm-greeks-limits"},"限额"),e(" 网格，也共用一个执行台。日常最容易犯的错是双记账：价值的时间衰减是 Theta，进盈亏解释；Delta 的时间漂移是 charm，进对冲预留——把两者加成一个「时间风险」既重复计算，又掩盖了各自的管理动作。")],-1)),(n(),i(s,null,{default:r(()=>[m(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%8E%B0%E8%B4%A7%E5%8A%A8%E4%B8%80%E6%A0%BC%22%5D%20--%3E%20G%5B%22Gamma%20%E8%AF%B4%E8%A1%A5%E5%A4%9A%E5%B0%91%22%5D%0A%20%20V%5B%22%E6%B3%A2%E5%8A%A8%E5%8A%A8%E4%B8%80%E6%A0%BC%22%5D%20--%3E%20VN%5B%22Vanna%20%E8%AF%B4%E8%A1%A5%E5%A4%9A%E5%B0%91%22%5D%0A%20%20T%5B%22%E4%BB%80%E4%B9%88%E9%83%BD%E4%B8%8D%E5%8A%A8%20%E8%BF%87%E4%B8%80%E5%A4%9C%22%5D%20--%3E%20C%5B%22Charm%20%E8%AF%B4%E8%A1%A5%E5%A4%9A%E5%B0%91%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%89%A7%E8%A1%8C%E5%8F%B0%20%E8%A1%A5%20Delta%22%5D%0A%20%20VN%20--%3E%20H%0A%20%20C%20--%3E%20H%0A%20%20T%20--%3E%20TH%5B%22Theta%20%E5%8F%AA%E8%BF%9B%E7%9B%88%E4%BA%8F%E8%A7%A3%E9%87%8A%22%5D%0A%20%20TH%20--%3E%20X%5B%22%E4%B8%8E%20charm%20%E5%88%86%E5%BC%80%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20C%20--%3E%20X%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p>不这么做会错在哪：不排班的台在到期周被「无缘无故触发再平衡」折磨——其实是 charm 把 Delta 带出了带宽；不区分符号口径的台，聚合出的 vanna 与市场 <a href="/quant/dealer-vanna-charm-flows">经销商流</a> 反号，隔夜情景形同虚设。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Vanna 与 charm 都不可直接交易：没有纯时间工具，也没有纯交叉工具，只能用 <a href="/quant/vanna-volga">Vanna / Volga 三点</a> 的香草组合近似，残差照旧。模型依赖要诚实：sticky strike 与 sticky delta 下的 charm 不同，<a href="/quant/sticky-delta-strike">切片搬动规则</a> 换了，隔夜漂移跟着换。最后，时钟项只覆盖 \\(\\mathrm{d}S=\\mathrm{d}\\sigma=0\\) 的世界，跳空仍要回 <a href="/quant/overnight-gap-hedge">隔夜情景</a>；charm 不是跳空的替代品，只是它的低阶近似。</p><p><span class="marginnote">常见误区：初学者容易把 Theta 与 charm 混成一个笼统的「时间风险」。其实价值衰减是 Theta、进盈亏解释；Delta 漂移是 charm、进对冲预留。合成一本账，既重复计算，又看不出各自该做的管理动作。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Vanna 是 Delta 对波动，charm 是 Delta 对时间；现货不动账本也在走。</li><li>记号各家不一，偏导定义必须钉进账本字段，聚合才有意义。</li><li>每日例行：时钟项乘 \\(\\Delta t\\)、波动项走情景、目标 Delta 留偏移、晨会排班。</li><li>Theta 进盈亏，charm 进预留，双记账会同时污染两本账。</li><li>Vanna / charm 不可直接交易，只能三点近似；跳空仍归隔夜情景管。</li><li>出处：据 Hull, <em>Options, Futures, and Other Derivatives</em>；运营口径与聚合方法据期权做市实务整理。</li></ul>',6))])}const g=h(B,[["render",d]]);export{q as __pageData,g as default};
